23	class HandoffController
24	{
25	public:
26	  HandoffController(Trigger trigger, DmiBus& bus)
27	      : trigger_{std::move(trigger)}, drain_{bus}
28	  {}
29	
30	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
31	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
32	  // a per-field DM Abstract Command on every handoff.
33	  void set_passthrough_input(hybrid_state_v1 input)
34	  {
35	    passthrough_ = input;
36	  }
37	
38	  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
39	  // derivation, which needs to read scanned EXIT PCs without consuming them.
40	  auto trigger() const -> const Trigger& { return trigger_; }
41	
42	  template<typename GprProbe>
43	  auto on_retire(uint64_t pc, GprProbe&& read_gpr)
44	    -> std::optional<hybrid_state_v1>
45	  {
46	    if constexpr (requires { trigger_.observe_commit(); }) {
47	      trigger_.observe_commit();
48	    }
49	    const auto hit = trigger_.lookup(pc);
50	    if (!hit) return std::nullopt;
51	
52	    bool fire = false;
53	    switch (hit->kind) {
54	    case HYBRID_HANDOFF_EXIT:
55	      fire = true;
56	      break;
57	    case HYBRID_HANDOFF_RUNTIME: {
58	      const auto rs1 = decode_csrrw_rs1(hit->insn);
59	      fire = (read_gpr(rs1) == 1u);
60	      break;
61	    }
62	    case HYBRID_HANDOFF_ENTER:  // entry is QEMU's job; vsim ignores it
63	    case HYBRID_HANDOFF_NONE:
64	      break;
65	    }
66	    if (!fire) return std::nullopt;
67	    if (passthrough_) return drain_.drain_with_passthrough(*passthrough_);
68	    return drain_.drain();
69	  }
70	
71	private:
72	  Trigger trigger_;
73	  StateDrain drain_;
74	  std::optional<hybrid_state_v1> passthrough_;
75	};
